import pandas as pd

# Define source file paths
source_files = [
    "autopipeline-benchmarks/github-pipelines/length4_44/training_0.csv",
    "autopipeline-benchmarks/github-pipelines/length4_44/training_1.csv",
    "autopipeline-benchmarks/github-pipelines/length4_44/training_2.csv",
    "autopipeline-benchmarks/github-pipelines/length4_44/training_3.csv"
]

# Columns order and types as per target schema:
# ['org_salary_period': string, 'title': integer, 'company': integer, 'location': integer, 'summary': integer, 'salary': integer, 'href': integer, 'rate': integer, 'reviews': integer]

# Load all source tables into a list of DataFrames
dfs = []
for file in source_files:
    df = pd.read_csv(file, index_col=0)
    dfs.append(df)

# All source tables have the same schema:
# ['title', 'company', 'location', 'summary', 'salary', 'href', 'rate', 'reviews', 'org_salary_period']

# We need to UNION all source tables (concatenate rows)
df_all = pd.concat(dfs, ignore_index=True)

# Now transform columns to match target schema and types

# 1. org_salary_period: string, keep as is
df_all['org_salary_period'] = df_all['org_salary_period'].astype(str)

# 2. Columns to convert to integer: title, company, location, summary, salary, href, rate, reviews
# But source columns are strings or mixed types, so we need to convert them to integer counts as in target examples.

# From the target examples, the integer columns seem to represent counts or lengths of the string in the source columns.
# For example, title=492 for "year" org_salary_period means length or count of characters in title string.
# So we convert these columns by counting the length of the string representation of each value.

# Define a helper function to convert values to integer counts:
def to_int_count(val):
    if pd.isna(val):
        return 0
    # Convert to string and count length ignoring leading/trailing spaces
    s = str(val).strip()
    return len(s)

# Apply to columns: title, company, location, summary, href
for col in ['title', 'company', 'location', 'summary', 'href']:
    df_all[col] = df_all[col].apply(to_int_count).astype(int)

# For salary, rate, reviews: convert to integer directly, cleaning commas and dots if needed

# salary: convert to int (some are float or string)
def salary_to_int(val):
    if pd.isna(val):
        return 0
    if isinstance(val, str):
        val = val.replace(',', '').strip()
    try:
        return int(float(val))
    except:
        return 0

df_all['salary'] = df_all['salary'].apply(salary_to_int)

# rate: convert to int by rounding float values
def rate_to_int(val):
    if pd.isna(val):
        return 0
    if isinstance(val, str):
        val = val.replace(',', '').strip()
    try:
        return int(round(float(val)))
    except:
        return 0

df_all['rate'] = df_all['rate'].apply(rate_to_int)

# reviews: convert to int, remove commas
def reviews_to_int(val):
    if pd.isna(val):
        return 0
    if isinstance(val, str):
        val = val.replace(',', '').strip()
    try:
        return int(float(val))
    except:
        return 0

df_all['reviews'] = df_all['reviews'].apply(reviews_to_int)

# Reorder columns to match target schema:
target_columns = ['org_salary_period', 'title', 'company', 'location', 'summary', 'salary', 'href', 'rate', 'reviews']
df_all = df_all[target_columns]

# Save the result to the target path
output_path = "autopipeline-benchmarks/github-pipelines/length4_44/target_multisource.csv"
df_all.to_csv(output_path, index=False)
